extern printf(fmt: string, ...);

# Create meaningful type names
type UserID = int;
type Score = int;
type Percentage = float;

struct User {
    id: UserID,
    name: string,
    score: Score,
}

frame calculateGrade(score: Score) ret Percentage {
    return cast<float>(score) / 100.0 * 100.0;
}

frame printUser(u: *User) {
    local grade: Percentage = calculateGrade(u.score);
    printf("User #%d: %s\n", u.id, u.name);
    printf("  Score: %d (%.1f%%)\n", u.score, grade);
}

frame main() ret int {
    local alice: User = User {
        id: 1001,
        name: "Alice",
        score: 95
    };

    local bob: User = User {
        id: 1002,
        name: "Bob",
        score: 87
    };

    printUser(&alice);
    printUser(&bob);

    return 0;
}

