# Function pointer types
type BinaryOp = Lambda<int>(int, int);
type Predicate = Lambda<bool>(int);
type Transformer = Lambda<int>(int);

# Use the aliases
frame apply(a: int, b: int, op: BinaryOp) ret int {
    return op(a, b);
}

frame filter(values: *int, len: int, pred: Predicate, out: *int) ret int {
    local count: int = 0;
    loop (local i: int = 0; i < len; i = i + 1) {
        if (pred(*(values + i))) {
            *(out + count) = *(values + i);
            count = count + 1;
        }
    }
    return count;
}

frame main() ret int {
    # Use BinaryOp
    local add: BinaryOp = |a: int, b: int| ret int { return a + b; };
    local mul: BinaryOp = |a: int, b: int| ret int { return a * b; };

    printf("apply(5, 3, add) = %d\n", apply(5, 3, add));
    printf("apply(5, 3, mul) = %d\n", apply(5, 3, mul));

    # Use Predicate
    local isEven: Predicate = |x: int| ret bool { return x % 2 == 0; };

    local nums: int[8] = [1, -2, 3, -4, 5, 6, -7, 8];
    local filtered: int[8];
    local count: int;

    count = filter(&nums[0], 8, isEven, &filtered[0]);
    printf("\nEven numbers: ");
    loop (local i: int = 0; i < count; i = i + 1) {
        printf("%d ", filtered[i]);
    }
    printf("\n");

    return 0;
}

