# Pointer types
type IntPtr = *int;
type StringArray = string[];

# Tuple types
type Point2D = (int, int);
type RGB = (int, int, int);

# Nested types
type Matrix2x2 = int[2][2];

frame printPoint(p: Point2D) {
    local (x: int, y: int) = p;
    printf("Point(%d, %d)\n", x, y);
}

frame printColor(c: RGB) {
    local (r: int, g: int, b: int) = c;
    printf("RGB(%d, %d, %d)\n", r, g, b);
}

frame printMatrix(m: Matrix2x2) {
    printf("[ %d %d ]\n", m[0][0], m[0][1]);
    printf("[ %d %d ]\n", m[1][0], m[1][1]);
}

frame main() ret int {
    # Point2D usage
    local origin: Point2D = (0, 0);
    local point: Point2D = (10, 20);
    printf("Origin: ");
    printPoint(origin);
    printf("Point: ");
    printPoint(point);

    # RGB usage
    local red: RGB = (255, 0, 0);
    local blue: RGB = (0, 0, 255);
    printf("\nRed: ");
    printColor(red);
    printf("Blue: ");
    printColor(blue);

    # Matrix usage
    local identity: Matrix2x2 = [[1, 0], [0, 1]];
    printf("\nIdentity Matrix:\n");
    printMatrix(identity);

    return 0;
}

