# Generic enums for optional/result patterns
# (Note: BPL stdlib has Maybe<T> and Outcome<T, E> - we use
# different names here to demonstrate creating your own)
enum Maybe<T> {
    Some(T),
    None,
}

enum Outcome<T, E> {
    Ok(T),
    Err(E),
}

# Using generic types directly
frame safeDivide(a: int, b: int) ret Maybe<int> {
    if (b == 0) {
        return Maybe<int>.None;
    }
    return Maybe<int>.Some(a / b);
}

frame parseInt(s: string) ret Outcome<int, string> {
    # Simplified: only handles single digits
    if (s == "0") { return Outcome<int, string>.Ok(0); }
    if (s == "1") { return Outcome<int, string>.Ok(1); }
    if (s == "2") { return Outcome<int, string>.Ok(2); }
    if (s == "3") { return Outcome<int, string>.Ok(3); }
    return Outcome<int, string>.Err("Invalid number");
}

frame main() ret int {
    # Maybe<int> usage
    local result1: Maybe<int> = safeDivide(10, 2);
    local result2: Maybe<int> = safeDivide(10, 0);

    match (result1) {
        Maybe<int>.Some(v) => printf("10/2 = %d\n", v),
        Maybe<int>.None => printf("10/2 = undefined\n"),
    }

    match (result2) {
        Maybe<int>.Some(v) => printf("10/0 = %d\n", v),
        Maybe<int>.None => printf("10/0 = undefined\n"),
    }

    # Outcome<int, string> usage
    local parsed: Outcome<int, string> = parseInt("3");
    match (parsed) {
        Outcome<int, string>.Ok(n) => printf("\nParsed: %d\n", n),
        Outcome<int, string>.Err(e) => printf("\nError: %s\n", e),
    }

    return 0;
}

