extern printf(fmt: string, ...);

type StatusCode = int;
type JSONBody = string;
type Header = (string, string);
type Response = (StatusCode, JSONBody);

frame makeResponse(code: StatusCode, body: JSONBody) ret Response {
    return (code, body);
}

frame main() ret int {
    local success: Response = makeResponse(200, "{\"ok\": true}");
    local notFound: Response = makeResponse(404, "{\"error\": \"Not found\"}");

    local (code1: int, body1: string) = success;
    printf("Response 1: %d - %s\n", code1, body1);

    local (code2: int, body2: string) = notFound;
    printf("Response 2: %d - %s\n", code2, body2);

    return 0;
}
